    st.ioSize = 65536;
    st.totalBytes = 512ull << 20;
    st.freeBytes = 256ull << 20;
    st.availableBytes = 256ull << 20;
    st.usedBytes = 256ull << 20;
    st.totalFiles = 4096;
    st.freeFiles = 4000;
