    unsigned char *m = mmap(NULL, 65536, PROT_READ, MAP_SHARED, mfd, 0);
    if (m == MAP_FAILED) { printf("  %-6d mmap failed: %s\n", grant, strerror(errno)); close(mfd); continue; }
